// spinicon.gif embedded as a Base64 data URI
const SPIN_ICON_BASE64 = "";
const SPIN_ICON_DATA_URI = "data:image/gif;base64," + SPIN_ICON_BASE64;

// Usage:
//   document.getElementById("icon").src = SPIN_ICON_DATA_URI;
//   or: new Image().src = SPIN_ICON_DATA_URI;

if (typeof module !== "undefined") module.exports = { SPIN_ICON_BASE64, SPIN_ICON_DATA_URI };
